class Example {
    static class Board { int raw = 4, normalized, result; }
    static int normalize(Board b) {
        if (b.normalized != 0) return 0;
        b.normalized = b.raw + 1;
        return 1;
    }
    static int derive(Board b) {
        if (b.normalized == 0 || b.result != 0) return 0;
        b.result = b.normalized * 2;
        return 1;
    }
    static int demo() {
        Board b = new Board(); int changed = 1;
        while (changed != 0) changed = derive(b) + normalize(b);
        return b.result;
    }
}

package main
type Board struct { Raw, Normalized, Result int }
func normalize(b *Board) int {
    if b.Normalized != 0 { return 0 }
    b.Normalized = b.Raw + 1
    return 1
}
func derive(b *Board) int {
    if b.Normalized == 0 || b.Result != 0 { return 0 }
    b.Result = b.Normalized * 2
    return 1
}
func demo() int {
    b := &Board{Raw: 4}
    changed := 1
    for changed != 0 { changed = derive(b) + normalize(b) }
    return b.Result
}

import java.util.function.IntUnaryOperator;
class Example {
    static class Kernel {
        IntUnaryOperator extension = x -> x * 2;
        void install(IntUnaryOperator implementation) { extension = implementation; }
        int execute(int value) { return extension.applyAsInt(value); }
    }
    static int demo() {
        Kernel kernel = new Kernel();
        int first = kernel.execute(5);
        kernel.install(x -> x * 3);
        return first + kernel.execute(5);
    }
}

package main
type Kernel struct { extension func(int) int }
func (k *Kernel) Install(implementation func(int) int) { k.extension = implementation }
func (k *Kernel) Execute(value int) int { return k.extension(value) }
func demo() int {
    k := &Kernel{extension: func(x int) int { return x * 2 }}
    first := k.Execute(5)
    k.Install(func(x int) int { return x * 3 })
    return first + k.Execute(5)
}

